// TEMPORARY (Field inbox [TEST] clip hand-off): serves a synthetic 12 s color-bars + 440 Hz tone clip so it can be copied into the media library. Deleted right after use.
const B64 = "";
Deno.serve(() => {
  const bin = atob(B64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i += 1) out[i] = bin.charCodeAt(i);
  return new Response(out, { headers: { "Content-Type": "video/mp4", "Content-Disposition": "inline; filename=field-inbox-test-site-visit.mp4" } });
});
